CREATE TABLE products (id INTEGER PRIMARY KEY AUTOINCREMENT,sku TEXT UNIQUE NOT NULL,ttac_serial TEXT NOT NULL,batch_code TEXT NOT NULL,expiry_label TEXT NOT NULL,cold_chain INTEGER NOT NULL DEFAULT 0,replenish_days INTEGER NOT NULL DEFAULT 45,name_fa TEXT NOT NULL,name_en TEXT NOT NULL,brand TEXT NOT NULL DEFAULT '',category TEXT NOT NULL,description TEXT NOT NULL,ingredients TEXT,usage_method TEXT,country TEXT,volume TEXT,original_price INTEGER NOT NULL,sale_price INTEGER NOT NULL,discount_percent INTEGER NOT NULL DEFAULT 0,stock INTEGER NOT NULL DEFAULT 0,low_stock_threshold INTEGER NOT NULL DEFAULT 5,published INTEGER NOT NULL DEFAULT 1,image_key TEXT NOT NULL DEFAULT 'gatieau_whitening',wishlisted INTEGER NOT NULL DEFAULT 0,benefits TEXT,long_description TEXT,seo_title TEXT,seo_description TEXT,keywords TEXT,instagram_caption TEXT,youtube_caption TEXT,telegram_caption TEXT,whatsapp_caption TEXT,image_path TEXT,ai_generated INTEGER NOT NULL DEFAULT 0);
